package generator

import (
	"fmt"
	"io"
	"sort"
	"strings"
)

// GenerateProtoDefinition emits a proto3 schema file with one message per
// Args/Response DTO defined in the access resource yaml. Used by A4 phase 15:
// the messages mirror the auto-generated config/args.go DTO structs so that
// each DTO can later be transmitted as a typed proto (replacing the legacy
// ToObject() / FromObject() ObjectMap path).
//
// Field-type mapping:
//
//	string                  → string
//	bool, bool_enable       → bool
//	time.Duration           → int64 (nanoseconds; converted on Go-side)
//	[]string                → repeated string
//	objproto.ConnectionID   → string (uses ConnectionID.String() representation)
//	*objproto.ConnectionID  → string (empty when nil)
//	uint32                  → uint32
//	uint64                  → uint64
//	netip.Addr              → string (uses Addr.String() representation)
//	[]*pb.PortInfo          → repeated PortInfo (imports router_service.proto)
//
// Custom response object_format strings are not translated here; the
// affected response DTOs still expose a Go-side ToObject() that handles
// them, but the proto schema treats them like any other field-list DTO.
func GenerateProtoDefinition(out io.Writer, input *Input) {
	d := input
	writer := &Writer{W: out}
	writer.Printf("// Code generated by ksdk/access/generator. DO NOT EDIT.\n")
	writer.Printf("syntax = \"proto3\";\n\n")
	writer.Printf("package ksdk.access;\n\n")
	writer.Printf("option go_package = \"github.com/on-keyday/kscale/protobuf/proto/access\";\n\n")
	if imports := definitionWKTImports(d.Definition); len(imports) > 0 {
		for _, imp := range imports {
			writer.Printf("import %q;\n", imp)
		}
		writer.Printf("\n")
	}
	writer.Printf("// PortInfo is re-defined locally rather than imported to keep this\n")
	writer.Printf("// schema standalone; the field set must mirror\n")
	writer.Printf("// protobuf/proto/router_service.proto's PortInfo.\n")
	writer.Printf("message PortInfo {\n")
	writer.Printf("    uint32 port = 1;\n")
	writer.Printf("    string protocol = 2;\n")
	writer.Printf("}\n\n")

	// args DTOs
	type emitted struct {
		name   string
		fields []ActionArg
	}
	var argsDTOs []emitted
	var responseDTOs []emitted
	for _, r := range d.Definition.Resources {
		for _, a := range r.Actions {
			argsDTOs = append(argsDTOs, emitted{
				name:   fmt.Sprintf("Resource%sAction%sArgsDTO", toCamelCase(r.Name), toCamelCase(a.Name)),
				fields: a.Args,
			})
			if a.Response != nil && a.Response.Use == nil {
				responseDTOs = append(responseDTOs, emitted{
					name:   fmt.Sprintf("Resource%sAction%sResponseDTO", toCamelCase(r.Name), toCamelCase(a.Name)),
					fields: a.Response.Fields,
				})
			}
		}
	}
	sort.SliceStable(argsDTOs, func(i, j int) bool { return argsDTOs[i].name < argsDTOs[j].name })
	sort.SliceStable(responseDTOs, func(i, j int) bool { return responseDTOs[i].name < responseDTOs[j].name })

	writer.Printf("// --- args DTOs ---\n\n")
	for _, dto := range argsDTOs {
		emitProtoMessage(writer, dto.name, dto.fields)
	}
	writer.Printf("// --- response DTOs ---\n\n")
	for _, dto := range responseDTOs {
		emitProtoMessage(writer, dto.name, dto.fields)
	}
}

// GenerateProtoServices emits a standalone proto (package ksdk.rpc, go_package
// protobuf/proto) containing one `service {Resource}Service` per resource with
// rpc_service: true. It is emitted into the protobuf/proto (pb) package — NOT
// access.proto — because the generated Register*Server depends on the rpc
// package, and pbaccess sits inside the rpc -> trsf -> pbagent -> pbaccess
// import chain (putting a Register*Server in pbaccess would close that cycle).
// The DTO messages live in package ksdk.access, so they are referenced with the
// `ksdk.access.` qualifier and access.proto is imported.
// useResponseProto maps a response `use:` Go type (resource.yaml
// `response: { use: X }`) to its proto message name and the .proto file that
// must be imported to reference it. The generated service proto is package
// ksdk.rpc / go_package protobuf/proto, and the `use` proto messages currently
// live in that same package, so the message is referenced unqualified. Extend
// this map when a resource opts into rpc_service with a new external response
// type (a missing entry panics rather than silently degrading to Empty).
var useResponseProto = map[string]struct{ message, importPath string }{
	"wkt.Empty":                 {"google.protobuf.Empty", "google/protobuf/empty.proto"},
	"pb.WasmListResponse":       {"WasmListResponse", "proto/wasm_service.proto"},
	"pb.ListAddrPortResponse":   {"ListAddrPortResponse", "proto/router_service.proto"},
	"pb.ACLDiffResponse":        {"ACLDiffResponse", "proto/router_service.proto"},
	"pb.FilesList":              {"FilesList", "proto/dp_service.proto"},
	"pb.TransferInternalState":  {"TransferInternalState", "proto/dp_service.proto"},
	"pb.TransferInternalStates": {"TransferInternalStates", "proto/dp_service.proto"},
	"pb.LogRecord":              {"LogRecord", "proto/dp_service.proto"},
	"pb.ChatEvent":              {"ChatEvent", "proto/monitor_chat.proto"},
	// StatBatch lives in proto package ksdk.stat (proto/stat/stat.proto), not
	// ksdk.rpc, so it is referenced with the ksdk.stat. qualifier (the only
	// cross-package use: entry so far). Used by dp_management.realtime_stats
	// server-streaming.
	"pbstat.StatBatch": {"ksdk.stat.StatBatch", "proto/stat/stat.proto"},
}

func GenerateProtoServices(out io.Writer, input *Input) {
	d := input
	writer := &Writer{W: out}
	imports := map[string]bool{"proto/access/access.proto": true}
	var svcResources []ResourceTemplate
	for _, r := range d.Definition.Resources {
		if !r.RpcService {
			continue
		}
		svcResources = append(svcResources, r)
		for _, a := range r.rpcActions() {
			imports[responseImport(&a)] = true
		}
	}
	importList := make([]string, 0, len(imports))
	for imp := range imports {
		importList = append(importList, imp)
	}
	sort.Strings(importList)
	writer.Printf("// Code generated by ksdk/access/generator. DO NOT EDIT.\n")
	writer.Printf("syntax = \"proto3\";\n\n")
	writer.Printf("package ksdk.rpc;\n\n")
	writer.Printf("option go_package = \"github.com/on-keyday/kscale/protobuf/proto\";\n\n")
	for _, imp := range importList {
		writer.Printf("import %q;\n", imp)
	}
	writer.Printf("\n")
	for _, r := range svcResources {
		emitProtoService(writer, &r)
	}
}

// responseType / responseImport resolve an action's RPC response: an inline
// generated ResponseDTO (no `use`), an external `use:` type (looked up in
// useResponseProto), or google.protobuf.Empty when the action has no response.
func responseType(svc string, a *Action) string {
	if a.Response == nil {
		return "google.protobuf.Empty"
	}
	if a.Response.Use != nil {
		u, ok := useResponseProto[*a.Response.Use]
		if !ok {
			panic(fmt.Errorf("GenerateProtoServices: response use type %q has no proto mapping (add it to useResponseProto)", *a.Response.Use))
		}
		return u.message
	}
	return fmt.Sprintf("ksdk.access.Resource%sAction%sResponseDTO", svc, toCamelCase(a.Name))
}

func responseImport(a *Action) string {
	if a.Response == nil {
		return "google/protobuf/empty.proto"
	}
	if a.Response.Use != nil {
		u, ok := useResponseProto[*a.Response.Use]
		if !ok {
			panic(fmt.Errorf("GenerateProtoServices: response use type %q has no proto mapping (add it to useResponseProto)", *a.Response.Use))
		}
		return u.importPath
	}
	// inline ResponseDTO lives in access.proto (always imported)
	return "proto/access/access.proto"
}

// emitProtoService emits a `service {Resource}Service { ... }` block with one
// unary rpc per action: request は常に ArgsDTO、response は inline ResponseDTO
// (a.Response.Use == nil)・外部 use: 型 (useResponseProto)・無し時は
// google.protobuf.Empty。inline DTO は package ksdk.access にあるので
// `ksdk.access.` 修飾で参照する。
func emitProtoService(writer *Writer, r *ResourceTemplate) {
	svc := toCamelCase(r.Name)
	writer.Printf("service %sService {\n", svc)
	for _, a := range r.rpcActions() {
		reqType := fmt.Sprintf("ksdk.access.Resource%sAction%sArgsDTO", svc, toCamelCase(a.Name))
		if a.isStreamingResponse() {
			writer.Printf("    rpc %s(%s) returns (stream %s);\n", toCamelCase(a.Name), reqType, responseType(svc, &a))
		} else {
			writer.Printf("    rpc %s(%s) returns (%s);\n", toCamelCase(a.Name), reqType, responseType(svc, &a))
		}
	}
	writer.Printf("}\n\n")
}

func emitProtoMessage(writer *Writer, msgName string, fields []ActionArg) {
	writer.Printf("message %s {\n", msgName)
	for i, f := range fields {
		protoType := goTypeToProtoType(f.Type)
		if protoType == "" {
			writer.Printf("    // FIELD SKIPPED: unsupported type %q for field %q\n", f.Type, f.Name)
			continue
		}
		writer.Printf("    %s %s = %d%s;\n", protoType, f.Name, i+1, protoFieldOptions(f.Type))
	}
	writer.Printf("}\n\n")
}

// protoFieldOptions returns the proto field-option suffix (e.g. ` [(ksdk.hold) =
// "time.Time"]`) for a Go type the plugin holds as a non-default Go type — the
// WKT-backed time.Time / time.Duration. Empty for plain fields.
func protoFieldOptions(goType string) string {
	switch goType {
	case "time.Time":
		return ` [(ksdk.hold) = "time.Time"]`
	case "time.Duration":
		return ` [(ksdk.hold) = "time.Duration"]`
	}
	return ""
}

// definitionWKTImports returns the .proto imports access.proto needs for the
// well-known-type-backed fields it contains: timestamp.proto for time.Time,
// duration.proto for time.Duration, plus ksdk_options.proto (for the (ksdk.hold)
// extension) when either is present. Returned sorted; empty when none are used.
func definitionWKTImports(d *Definition) []string {
	var usesTime, usesDur bool
	check := func(fields []ActionArg) {
		for _, f := range fields {
			switch f.Type {
			case "time.Time":
				usesTime = true
			case "time.Duration":
				usesDur = true
			}
		}
	}
	for _, r := range d.Resources {
		for _, a := range r.Actions {
			check(a.Args)
			if a.Response != nil {
				check(a.Response.Fields)
			}
		}
	}
	var imports []string
	if usesDur {
		imports = append(imports, "google/protobuf/duration.proto")
	}
	if usesTime {
		imports = append(imports, "google/protobuf/timestamp.proto")
	}
	if usesTime || usesDur {
		imports = append(imports, "proto/ksdkpb/ksdk_options.proto")
	}
	sort.Strings(imports)
	return imports
}

// emitDTOFieldToProto emits Go code that copies one DTO field into its
// corresponding pbaccess proto field. The DTO field is referenced as
// `dto.<CamelName>` and the proto field as `out.<CamelName>`. Unsupported
// types are skipped with a TODO comment.
func emitDTOFieldToProto(w *Writer, f ActionArg) {
	camel := toCamelCase(f.Name)
	switch f.Type {
	case "string":
		w.Printf("out.%s = dto.%s\n", camel, camel)
	case "bool", "bool_enable":
		w.Printf("out.%s = dto.%s\n", camel, camel)
	case "time.Duration":
		w.Printf("out.%s = int64(dto.%s)\n", camel, camel)
	case "[]string":
		w.Printf("out.%s = dto.%s\n", camel, camel)
	case "objproto.ConnectionID":
		w.Printf("out.%s = dto.%s.String()\n", camel, camel)
	case "*objproto.ConnectionID":
		w.Printf("if dto.%s != nil { out.%s = dto.%s.String() }\n", camel, camel, camel)
	case "uint32", "uint64":
		w.Printf("out.%s = dto.%s\n", camel, camel)
	case "[]byte":
		w.Printf("out.%s = dto.%s\n", camel, camel)
	case "netip.Addr":
		w.Printf("out.%s = dto.%s.String()\n", camel, camel)
	case "[]*pb.PortInfo":
		w.Printf("for _, p := range dto.%s {\n", camel)
		w.Indented(func(ww *Writer) {
			ww.Printf("if p == nil { continue }\n")
			ww.Printf("out.%s = append(out.%s, &pbaccess.PortInfo{Port: uint32(p.Port), Protocol: p.Protocol})\n", camel, camel)
		})
		w.Printf("}\n")
	default:
		w.Printf("// TODO: ToProto skipped field %q (type %q)\n", f.Name, f.Type)
	}
}

// emitDTOFieldFromProto emits Go code that copies one pbaccess field
// back into its DTO counterpart. The DTO field is referenced as
// `dto.<CamelName>` and the proto field as `src.<CamelName>`. Errors are
// returned for malformed inputs (e.g. invalid ConnectionID string).
// Unsupported types are skipped silently.
func emitDTOFieldFromProto(w *Writer, f ActionArg) {
	camel := toCamelCase(f.Name)
	switch f.Type {
	case "string":
		w.Printf("dto.%s = src.%s\n", camel, camel)
	case "bool", "bool_enable":
		w.Printf("dto.%s = src.%s\n", camel, camel)
	case "time.Duration":
		w.Printf("dto.%s = time.Duration(src.%s)\n", camel, camel)
	case "[]string":
		w.Printf("dto.%s = src.%s\n", camel, camel)
	case "objproto.ConnectionID":
		w.Printf("if src.%s != \"\" {\n", camel)
		w.Indented(func(ww *Writer) {
			ww.Printf("cid, err := objproto.ParseConnectionID(src.%s, 0)\n", camel)
			ww.Printf("if err != nil { return fmt.Errorf(\"invalid connection id for %s: %%w\", err) }\n", f.Name)
			ww.Printf("dto.%s = cid\n", camel)
		})
		w.Printf("}\n")
	case "*objproto.ConnectionID":
		w.Printf("if src.%s != \"\" {\n", camel)
		w.Indented(func(ww *Writer) {
			ww.Printf("cid, err := objproto.ParseConnectionID(src.%s, 0)\n", camel)
			ww.Printf("if err != nil { return fmt.Errorf(\"invalid connection id for %s: %%w\", err) }\n", f.Name)
			ww.Printf("dto.%s = &cid\n", camel)
		})
		w.Printf("}\n")
	case "uint32", "uint64":
		w.Printf("dto.%s = src.%s\n", camel, camel)
	case "[]byte":
		w.Printf("dto.%s = src.%s\n", camel, camel)
	case "netip.Addr":
		w.Printf("if src.%s != \"\" {\n", camel)
		w.Indented(func(ww *Writer) {
			ww.Printf("addr, err := netip.ParseAddr(src.%s)\n", camel)
			ww.Printf("if err != nil { return fmt.Errorf(\"invalid netip.Addr for %s: %%w\", err) }\n", f.Name)
			ww.Printf("dto.%s = addr\n", camel)
		})
		w.Printf("}\n")
	case "[]*pb.PortInfo":
		w.Printf("for _, p := range src.%s {\n", camel)
		w.Indented(func(ww *Writer) {
			ww.Printf("if p == nil { continue }\n")
			ww.Printf("dto.%s = append(dto.%s, &pb.PortInfo{Port: uint16(p.Port), Protocol: p.Protocol})\n", camel, camel)
		})
		w.Printf("}\n")
	default:
		w.Printf("// TODO: FromProto skipped field %q (type %q)\n", f.Name, f.Type)
	}
}

// goTypeToProtoType maps the parseMethodMap key (the Go type spelling used
// in resource.yaml) to a proto3 type. Empty string means "unsupported,
// skip this field".
func goTypeToProtoType(goType string) string {
	// time.Duration → int64 (nanoseconds)
	switch goType {
	case "string":
		return "string"
	case "bool", "bool_enable":
		return "bool"
	case "time.Duration":
		// Held as time.Duration via (ksdk.hold); plugin converts to/from
		// wkt.Duration. (Was int64 before the hold support — a duration_lte policy
		// condition needs the real time.Duration type.)
		return "google.protobuf.Duration"
	case "time.Time":
		// Held as time.Time on the Go side via the (ksdk.hold) option (see
		// protoFieldOptions); the plugin converts to/from wkt.Timestamp.
		return "google.protobuf.Timestamp"
	case "[]string":
		return "repeated string"
	case "objproto.ConnectionID", "*objproto.ConnectionID":
		return "string"
	case "uint32":
		return "uint32"
	case "uint64":
		return "uint64"
	case "[]byte":
		return "bytes"
	case "netip.Addr":
		return "string"
	case "[]*pb.PortInfo":
		return "repeated PortInfo"
	}
	// `[]obj:<MessageName>` — a repeated reference to another message in this
	// same access.proto (used by synthesized list responses, whose element is the
	// resource's GetResponseDTO). Emitted unqualified since it is same-package.
	if rest, ok := strings.CutPrefix(goType, "[]obj:"); ok {
		return "repeated " + rest
	}
	// Allow `pb.<Name>` to pass through as a message reference (rare).
	if strings.HasPrefix(goType, "pb.") {
		return strings.TrimPrefix(goType, "pb.")
	}
	if strings.HasPrefix(goType, "[]pb.") {
		return "repeated " + strings.TrimPrefix(goType, "[]pb.")
	}
	return ""
}
